#!/usr/bin/env node
/**
 * build-sidecar.mjs — build the Node headless-lane sidecar (T28, final owner).
 *
 * One command, two gates:
 *
 *   1. **Bundle.** `src-tauri/sidecar/src/index.ts` →
 *      `src-tauri/sidecar/sidecar.cjs` (+ `.cjs.map`) with
 *      `platform: node, target: node20, format: cjs, sourcemap: external`
 *      (DESIGN §5-2). The esbuild invocation itself lives in
 *      `src-tauri/sidecar/esbuild.mjs` because it also injects two build-time
 *      constants — the sidecar version and the exact installed versions of the
 *      five `@toragonite` packages — that `mesh.hello` must report and that a
 *      second, parallel esbuild config here would silently get wrong.
 *      This script drives it and then **verifies the artifact** against the four
 *      properties above, so a drift in that file fails the build here instead of
 *      at runtime inside a bundle.
 *   2. **Seam check.** `src-tauri/sidecar/scripts/check-seam.mjs` attributes
 *      every `child_process` launch call in the shipped bundle to its module and
 *      fails the build if one appears outside the blessed seams (DESIGN §5-7).
 *      That gate is what makes "every headless child is in the registry before it
 *      exists" a checked claim rather than a hope.
 *
 * It does not touch the vendored Node runtime — that is `scripts/fetch-node.sh`.
 * `tauri.conf.json > build.beforeBuildCommand` runs both, in that order.
 *
 * Usage:
 *   node scripts/build-sidecar.mjs            bundle + verify + seam check
 *   node scripts/build-sidecar.mjs --watch    esbuild watch loop (no gates)
 */

import { spawn } from 'node:child_process';
import { existsSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const sidecarDir = join(repoRoot, 'src-tauri', 'sidecar');
const esbuildScript = join(sidecarDir, 'esbuild.mjs');
const seamScript = join(sidecarDir, 'scripts', 'check-seam.mjs');
const nodeModules = join(sidecarDir, 'node_modules');
const entryPoint = join(sidecarDir, 'src', 'index.ts');
const bundle = join(sidecarDir, 'sidecar.cjs');
const bundleMap = join(sidecarDir, 'sidecar.cjs.map');

const watch = process.argv.includes('--watch');
const rel = (p) => relative(repoRoot, p);

/** Run `node <script> [args]` in the sidecar dir; resolve on exit 0, reject otherwise. */
function run(script, args = []) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [script, ...args], {
      cwd: sidecarDir,
      stdio: 'inherit',
      env: process.env,
    });
    child.on('error', reject);
    child.on('exit', (code, signal) => {
      if (code === 0) resolve();
      else
        reject(
          new Error(`${rel(script)} exited with ${signal ? `signal ${signal}` : `code ${code}`}`),
        );
    });
  });
}

function requireFile(path, hint) {
  if (!existsSync(path)) throw new Error(`[build-sidecar] ${rel(path)} is missing. ${hint}`);
}

/**
 * The artifact contract, checked on the bytes rather than on the config that
 * produced them: `sidecar.cjs` is a CommonJS bundle whose source map is a
 * *separate* file. `tauri.conf.json > bundle.resources` ships `sidecar.cjs`
 * alone (what `SidecarManager` runs as `<gilde-node> sidecar.cjs`); the map stays
 * in the source tree for local debugging — see `verifyBundleConfig`.
 */
function verifyArtifact() {
  requireFile(bundle, 'The esbuild step did not produce it.');
  requireFile(bundleMap, 'Expected an external source map (sourcemap: "external").');

  const code = readFileSync(bundle, 'utf8');
  const problems = [];

  if (code.includes('PLACEHOLDER — generated by')) {
    problems.push('it is still the pre-T17 placeholder, not a real bundle');
  }
  // format: cjs — esbuild's CJS output opens with "use strict" and uses require().
  if (!/^\s*"use strict";/.test(code)) {
    problems.push('it does not start with "use strict" (format should be cjs)');
  }
  if (/^\s*(?:export|import)\s/m.test(code)) {
    problems.push('it contains top-level ESM syntax (format should be cjs)');
  }
  // sourcemap: external — the map is written, but no comment links it, so the
  // shipped bundle carries no path from this machine.
  if (code.includes('//# sourceMappingURL=')) {
    problems.push('it carries a sourceMappingURL comment (sourcemap should be "external", not "linked")');
  }

  let map;
  try {
    map = JSON.parse(readFileSync(bundleMap, 'utf8'));
  } catch (err) {
    problems.push(`the source map is not valid JSON (${err.message})`);
  }
  if (map && (map.version !== 3 || !Array.isArray(map.sources) || map.sources.length === 0)) {
    problems.push('the source map is empty or not v3');
  }

  if (problems.length > 0) {
    throw new Error(
      `[build-sidecar] ${rel(bundle)} failed its contract:\n  - ${problems.join('\n  - ')}`,
    );
  }

  const kb = (p) => Math.round(statSync(p).size / 1024);
  console.log(
    `[build-sidecar] ${rel(bundle)} ${kb(bundle)} KB + ${kb(bundleMap)} KB map — cjs, node20, external map.`,
  );
}

/**
 * No source map in the app bundle. `sidecar.cjs.map` carries `sourcesContent`
 * (the sidecar's TypeScript, verbatim), and a release bundle is not the place
 * for it. The check reads the config the bundler reads, so re-adding the map to
 * `bundle.resources` fails here, before `tauri build` gets to copy it.
 */
function verifyBundleConfig() {
  const confPath = join(repoRoot, 'src-tauri', 'tauri.conf.json');
  const resources = JSON.parse(readFileSync(confPath, 'utf8')).bundle?.resources ?? [];
  const entries = Array.isArray(resources)
    ? resources
    : Object.entries(resources).flatMap(([from, to]) => [from, to]);
  const maps = entries.filter((p) => /\.map$/i.test(p) || /\*/.test(p));
  if (maps.length > 0) {
    throw new Error(
      `[build-sidecar] ${rel(confPath)} > bundle.resources would ship a source map or a glob: ${maps.join(', ')}. ` +
        'List shipped files explicitly; source maps are not shipped.',
    );
  }
}

async function main() {
  requireFile(entryPoint, 'The sidecar source tree is incomplete.');
  requireFile(esbuildScript, 'The sidecar build script is missing.');
  requireFile(nodeModules, 'Run: (cd src-tauri/sidecar && npm ci)');

  await run(esbuildScript, watch ? ['--watch'] : []);

  // --watch never returns; the gates below are one-shot and belong to a build.
  if (watch) return;

  verifyArtifact();
  verifyBundleConfig();

  requireFile(seamScript, 'The seam gate is missing; refusing to ship an unaudited bundle.');
  await run(seamScript);
}

main().catch((err) => {
  console.error(err.message ?? err);
  process.exit(1);
});
